import{_ as t,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"应用 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"应用程序容器","slug":"应用程序容器","link":"#应用程序容器","children":[{"level":4,"title":"将类型绑定到容器中","slug":"将类型绑定到容器中","link":"#将类型绑定到容器中","children":[]},{"level":4,"title":"从容器中解析类型","slug":"从容器中解析类型","link":"#从容器中解析类型","children":[]},{"level":4,"title":"将一个\\"共享\\"类型绑定到容器中","slug":"将一个-共享-类型绑定到容器中","link":"#将一个-共享-类型绑定到容器中","children":[]},{"level":4,"title":"将现有实例绑定到容器中","slug":"将现有实例绑定到容器中","link":"#将现有实例绑定到容器中","children":[]},{"level":4,"title":"将接口绑定到实现","slug":"将接口绑定到实现","link":"#将接口绑定到实现","children":[]},{"level":3,"title":"在哪里注册绑定","slug":"在哪里注册绑定","link":"#在哪里注册绑定","children":[]}]},{"level":2,"title":"服务提供者","slug":"服务提供者","link":"#服务提供者","children":[{"level":4,"title":"定义服务提供者","slug":"定义服务提供者","link":"#定义服务提供者","children":[]},{"level":4,"title":"在运行时注册服务提供者","slug":"在运行时注册服务提供者","link":"#在运行时注册服务提供者","children":[]}]},{"level":2,"title":"应用程序事件","slug":"应用程序事件","link":"#应用程序事件","children":[{"level":4,"title":"请求事件","slug":"请求事件","link":"#请求事件","children":[]},{"level":4,"title":"容器事件","slug":"容器事件","link":"#容器事件","children":[]}]},{"level":2,"title":"应用程序助手","slug":"应用程序助手","link":"#应用程序助手","children":[{"level":4,"title":"查找应用环境","slug":"查找应用环境","link":"#查找应用环境","children":[]},{"level":4,"title":"确定执行上下文","slug":"确定执行上下文","link":"#确定执行上下文","children":[]}]}],"relativePath":"2.x/zh-cn/services/application.md","filePath":"2.x/zh-cn/services/application.md"}'),r={name:"2.x/zh-cn/services/application.md"};function u(k,n,d,h,g,v){const p=s("pre-heading"),e=s("post-heading");return o(),c("div",null,[a(p),n[0]||(n[0]=l("h1",null,"应用",-1)),a(e),n[1]||(n[1]=i(`<p><a id="oc-application-container"></a></p><h2 id="应用程序容器"><a href="#应用程序容器" class="header-anchor">#</a> 应用程序容器</h2><p>控制反转(IoC)容器是用于管理类依赖关系的工具。 依赖注入是一种去除硬编码类依赖的方法。 相反，依赖项是在运行时注入的，因为可以轻松交换依赖项实现，从而提供更大的灵活性。</p><h4 id="将类型绑定到容器中"><a href="#将类型绑定到容器中" class="header-anchor">#</a> 将类型绑定到容器中</h4><p>IoC 容器可以通过两种方式解决依赖关系：通过闭包回调或自动解析。 首先，我们将探索闭包回调，可以将&quot;类型&quot;绑定到容器中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">FooBar</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="从容器中解析类型"><a href="#从容器中解析类型" class="header-anchor">#</a> 从容器中解析类型</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>当调用 <code>App::make</code> 方法时，会执行 Closure 回调并返回结果。</p><h4 id="将一个-共享-类型绑定到容器中"><a href="#将一个-共享-类型绑定到容器中" class="header-anchor">#</a> 将一个&quot;共享&quot;类型绑定到容器中</h4><p>有时您可能希望将某些内容绑定到只应解析一次的容器中，并且应在随后对容器的调用中返回相同的实例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">singleton</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">FooBar</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="将现有实例绑定到容器中"><a href="#将现有实例绑定到容器中" class="header-anchor">#</a> 将现有实例绑定到容器中</h4><p>您还可以使用 <code>instance</code> 方法将现有对象实例绑定到容器中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$foo</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Foo</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token variable">$foo</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="将接口绑定到实现"><a href="#将接口绑定到实现" class="header-anchor">#</a> 将接口绑定到实现</h4><p>在某些情况下，类可能依赖于接口实现，而不是&quot;具体类型&quot;。 在这种情况下，必须使用 <code>App::bind</code> 方法来通知容器要注入哪个接口实现：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;UserRepositoryInterface&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;DbUserRepository&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>现在考虑以下代码：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;UserRepositoryInterface&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>由于我们已将 <code>UserRepositoryInterface</code> 绑定到具体类型，<code>DbUserRepository</code> 将在创建时自动注入此控制器。</p><h3 id="在哪里注册绑定"><a href="#在哪里注册绑定" class="header-anchor">#</a> 在哪里注册绑定</h3><p>IoC 绑定，如 <a href="./events.html">事件处理程序</a>，通常属于&quot;引导代码&quot;类别。换句话说，它们让您的应用程序准备好实际处理请求，并且通常需要在实际调用路由或控制器之前执行。最常见的地方是<a href="./../plugin/registration.html#oc-registration-methods">插件注册文件</a>的<code>boot</code>方法。或者，插件可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，您可以使用该文件来放置 IoC 注册逻辑。</p><p><a id="oc-service-providers"></a></p><h2 id="服务提供者"><a href="#服务提供者" class="header-anchor">#</a> 服务提供者</h2><p>服务提供者是在单个位置创建库和执行组相关的 IoC 注册的好方法。在服务提供者中，您可以注册自定义身份验证驱动程序，使用 IoC 容器注册应用程序的存储库类，甚至设置自定义 Artisan 命令。</p><p>实际上，<a href="./../plugin/registration.html">插件注册文件</a>继承了服务提供者，大部分核心组件都包含服务提供者。为您的应用程序注册的所有服务提供者都列在 <code>config/app.php</code> 配置文件的 <code>providers</code> 数组中。</p><h4 id="定义服务提供者"><a href="#定义服务提供者" class="header-anchor">#</a> 定义服务提供者</h4><p>要创建服务提供者，只需扩展 <code>October\\Rain\\Support\\ServiceProvider</code> 类并定义 <code>register</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Support<span class="token punctuation">\\</span>ServiceProvider</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">FooServiceProvider</span> <span class="token keyword">extends</span> <span class="token class-name">ServiceProvider</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">register</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">app</span><span class="token operator">-&gt;</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Foo</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>请注意，在 <code>register</code> 方法中，您可以通过 <code>$this-&gt;app</code> 属性使用应用程序 IoC 容器。 一旦您创建了提供程序并准备将其注册到您的应用程序中，只需将其添加到您的 <code>app</code> 配置文件中的 <code>providers</code> 数组中。</p><h4 id="在运行时注册服务提供者"><a href="#在运行时注册服务提供者" class="header-anchor">#</a> 在运行时注册服务提供者</h4><p>您还可以在运行时使用 <code>App::register</code> 方法注册服务提供者：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FooServiceProvider&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="应用程序事件"><a href="#应用程序事件" class="header-anchor">#</a> 应用程序事件</h2><h4 id="请求事件"><a href="#请求事件" class="header-anchor">#</a> 请求事件</h4><p>您可以使用 <code>before</code> 和 <code>after</code> 方法在请求路由之前注册特殊事件：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">before</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 在路由请求之前执行的代码</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">after</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 路由请求后要执行的代码</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="容器事件"><a href="#容器事件" class="header-anchor">#</a> 容器事件</h4><p>服务容器每次解析对象时都会触发一个事件。 您可以使用 <code>resolving</code> 方法收听此事件：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$object</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 当容器解析任何类型的对象时调用...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$fooBar</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 当容器使用提示&quot;foo&quot;解析对象时调用...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme\\Blog\\Classes\\FooBar&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$fooBar</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 当容器解析&quot;FooBar&quot;类型的对象时调用...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如您所见，正在解析的对象将被传递给回调，允许您在对象被提供给其使用者之前设置对象的任何其他属性。</p><h2 id="应用程序助手"><a href="#应用程序助手" class="header-anchor">#</a> 应用程序助手</h2><h4 id="查找应用环境"><a href="#查找应用环境" class="header-anchor">#</a> 查找应用环境</h4><p>您可以使用 <code>environment</code> 方法来发现由 <a href="./../setup/configuration.html#oc-environment-configuration">环境配置</a> 确定的应用程序环境。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 生产</span>
<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">environment</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="确定执行上下文"><a href="#确定执行上下文" class="header-anchor">#</a> 确定执行上下文</h4><p>可以使用 <code>runningInBackend</code> 方法知道当前请求是否正在管理后端区域中执行。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">runningInBackend</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以使用 <code>runningInConsole</code> 方法检查执行代码是否发生在 <a href="./../console/commands.html">命令行界面</a> 中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">runningInConsole</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,51))])}const x=t(r,[["render",u]]);export{m as __pageData,x as default};
